import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:image/image.dart' as img;

import '../tool/site.dart';

/// Guards the web launch metadata for opencadirrigation.com: the three entry
/// pages (en at /, pt-BR at /pt/, es at /es/) generated by tool/gen_site.dart,
/// the redirect left at the old /en/, manifest, icons, robots, sitemap, 404
/// and brand assets.
void main() {
  const site = 'https://opencadirrigation.com/';
  (int, int) size(String path) {
    final i = img.decodePng(File(path).readAsBytesSync());
    expect(i, isNotNull, reason: path);
    return (i!.width, i.height);
  }

  Map<String, dynamic> jsonLdOf(String html) {
    final ld = RegExp(r'<script type="application/ld\+json">([\s\S]*?)</script>').firstMatch(html)!.group(1)!;
    return jsonDecode(ld) as Map<String, dynamic>;
  }

  test('design worker bundle is compiled next to the web app', () {
    // tool/build_worker.sh compiles lib/worker/design_worker.dart to web/design_worker.js
    final f = File('web/design_worker.js');
    expect(f.existsSync(), isTrue, reason: 'run tool/build_worker.sh');
    expect(f.lengthSync(), greaterThan(100000));
    expect(File('web/design_worker.js.deps').existsSync(), isFalse);
  });

  test('the pages, sitemap and 404 match the generator (tool/gen_site.dart)', () {
    for (final e in renderSite().entries) {
      final f = File('web/${e.key}');
      expect(f.existsSync(), isTrue, reason: e.key);
      expect(f.readAsStringSync(), e.value, reason: '${f.path} is out of date: run dart run tool/gen_site.dart');
    }
  });

  test('root index.html carries SEO, Open Graph, Twitter, icons, manifest and JSON-LD', () {
    final html = File('web/index.html').readAsStringSync();
    expect(html, contains('<base href="\$FLUTTER_BASE_HREF">'));
    expect(html, contains('<html lang="en">'), reason: 'English is the default: the root page is the English one');
    expect(html, contains('<link rel="canonical" href="$site">'));
    for (final needle in ['og:title', 'og:description', 'og:url', 'og:type', 'twitter:card', 'name="description"', 'name="viewport"', 'rel="manifest"', 'rel="apple-touch-icon"', 'hreflang="en"', 'hreflang="es"', 'hreflang="pt-BR"', 'hreflang="x-default"', 'theme-color', 'name="robots"', 'rel="preconnect"']) {
      expect(html, contains(needle), reason: needle);
    }
    expect(html, contains('content="${site}og-image.png"'));
    expect(html, contains('flutter_bootstrap.js'));
    expect(html, contains('flutter-first-frame'));
    expect(html, contains('gtag/js?id=$analyticsId'), reason: 'analytics live in tool/site.dart, not in the generated file');

    final graph = jsonLdOf(html)['@graph'] as List;
    expect(graph.map((e) => (e as Map)['@type']), containsAll(['Organization', 'WebSite', 'WebPage', 'SoftwareApplication', 'BreadcrumbList']));
    final app = graph.firstWhere((e) => (e as Map)['@type'] == 'SoftwareApplication') as Map;
    expect(app['url'], site);
    expect(app['name'], 'OpenCADIrrigation');
    expect(app['isAccessibleForFree'], isTrue);
    expect(html, isNot(contains('OpenCadIrrigation')));
    // title and description lengths search engines display in full
    final title = RegExp(r'<title>(.*?)</title>').firstMatch(html)!.group(1)!;
    expect(title.length, inInclusiveRange(30, 65), reason: title);
    final desc = RegExp(r'<meta name="description" content="(.*?)">').firstMatch(html)!.group(1)!;
    expect(desc.length, inInclusiveRange(80, 230), reason: desc);
  });

  test('the page body is real, readable content for crawlers and non-JS visitors', () {
    for (final l in siteLanguages) {
      final html = File('web/${l.file}').readAsStringSync();
      final t = siteText(l.code);
      expect(html, contains('<h1>${t.h1}</h1>'), reason: l.code);
      expect(RegExp(r'<h2 ').allMatches(html).length, 4, reason: '${l.code}: features, how, examples, faq');
      for (final (name, _) in t.features) {
        expect(html, contains('<h3>$name</h3>'), reason: '${l.code} $name');
      }
      for (final ex in t.examples) {
        expect(html, contains('href="${l.url}?example=${ex.id}"'), reason: '${l.code} ${ex.id}');
      }
      expect(html, contains('href="${l.url}?tutorial=1"'));
      expect(html, contains('<dt>${t.faq.first.$1}</dt>'));
      expect(html, contains('id="oci-landing"'));
      expect(html, contains("setAttribute('hidden'"), reason: 'hidden, not removed, on first frame');
      expect(html, contains('<noscript>'));
      // links to the other language versions
      for (final o in siteLanguages) {
        if (o.code != l.code) expect(html, contains('<a href="${o.url}" hreflang="${o.tag}"'), reason: '${l.code} → ${o.code}');
      }
    }
  });

  test('/pt/ and /es/ are localised entry pages rooted at the site root', () {
    for (final l in siteLanguages.where((l) => !l.isRoot)) {
      final html = File('web/${l.file}').readAsStringSync();
      expect(html, contains('<html lang="${l.tag}">'), reason: l.code);
      expect(html, contains('<base href="/">'), reason: 'the app and its assets live at the root');
      expect(html, contains('<link rel="canonical" href="${l.url}">'));
      expect(html, contains('<meta property="og:url" content="${l.url}">'));
      expect(html, contains('<meta property="og:locale" content="${l.ogLocale}">'));
      expect(html, contains('<link rel="alternate" hreflang="x-default" href="$site">'));
      expect(html, contains('flutter_bootstrap.js'));
      final graph = jsonLdOf(html)['@graph'] as List;
      final page = graph.firstWhere((e) => (e as Map)['@type'] == 'WebPage') as Map;
      expect(page['url'], l.url);
      expect(page['inLanguage'], l.tag);
      expect(html, isNot(contains(r'$FLUTTER_BASE_HREF')));
    }
    // the three pages say different things
    final titles = {for (final l in siteLanguages) siteText(l.code).title};
    expect(titles.length, 3);
  });

  test('the old /en/ address redirects to the root, query and all', () {
    final html = File('web/en/index.html').readAsStringSync();
    expect(html, contains('<meta name="robots" content="noindex, follow">'));
    expect(html, contains('<meta http-equiv="refresh" content="0; url=/">'));
    expect(html, contains("location.replace('/' + location.search + location.hash)"), reason: '/en/?example=garden keeps working');
    expect(html, contains('href="$site"'));
    expect(html, isNot(contains('flutter_bootstrap.js')), reason: 'a redirect stub, not a second copy of the app');
  });

  test('manifest.json is valid and every referenced file exists', () {
    final m = jsonDecode(File('web/manifest.json').readAsStringSync()) as Map<String, dynamic>;
    expect(m['name'], startsWith('OpenCADIrrigation'));
    expect(m['theme_color'], '#0D47A1');
    expect(m['lang'], 'en');
    for (final icon in m['icons'] as List) {
      final src = (icon as Map)['src'] as String;
      expect(File('web/$src').existsSync(), isTrue, reason: src);
      final (w, h) = size('web/$src');
      expect('${w}x$h', icon['sizes'], reason: src);
    }
    for (final s in m['screenshots'] as List) {
      expect(File('web/${(s as Map)['src']}').existsSync(), isTrue);
      expect(s['label'], isNotEmpty);
    }
    final urls = (m['shortcuts'] as List).map((s) => (s as Map)['url'] as String).toList();
    expect(urls, contains('./?tutorial=1'));
    expect(urls.where((u) => u.contains('example=')), isNotEmpty, reason: 'gallery shortcuts');
    for (final s in m['shortcuts'] as List) {
      expect((s as Map)['url'], anyOf(contains('tutorial=1'), contains('design=1'), contains('example=')));
    }
  });

  test('favicons, touch icon, Open Graph image, robots, sitemap, 404 and CNAME', () {
    expect(File('web/favicon.ico').lengthSync(), greaterThan(1000));
    expect(size('web/favicon-32.png'), (32, 32));
    expect(size('web/favicon-16.png'), (16, 16));
    expect(size('web/apple-touch-icon.png'), (180, 180));
    expect(size('web/og-image.png'), (1200, 630));
    expect(size('web/screenshots/design-1440x900.png'), (1440, 900));
    expect(size('web/brand/logo-square.png').$1, size('web/brand/logo-square.png').$2);
    final robots = File('web/robots.txt').readAsStringSync();
    expect(robots, contains('Sitemap: ${site}sitemap.xml'));
    expect(robots, contains('Allow: /'));
    expect(robots, isNot(contains('Disallow')));
    final sitemap = File('web/sitemap.xml').readAsStringSync();
    expect(sitemap, contains('<loc>$site</loc>'));
    expect(sitemap, contains('<loc>${site}pt/</loc>'));
    expect(sitemap, contains('<loc>${site}es/</loc>'));
    expect(sitemap, isNot(contains('<loc>${site}en/</loc>')), reason: 'English is the root page now');
    expect(sitemap, isNot(contains('?lang=')), reason: 'query URLs are not canonical pages');
    expect(RegExp('hreflang="x-default"').allMatches(sitemap).length, 3);
    expect(RegExp(r'<lastmod>\d{4}-\d\d-\d\d</lastmod>').allMatches(sitemap).length, 3);
    final notFound = File('web/404.html').readAsStringSync();
    expect(notFound, contains('noindex'));
    for (final l in siteLanguages) {
      expect(notFound, contains('href="${l.url}"'), reason: l.code);
    }
    expect(File('web/CNAME').readAsStringSync().trim(), 'opencadirrigation.com');
  });

  test('brand assets are bundled with the app', () {
    expect(File('assets/brand/logo-mark.png').existsSync(), isTrue);
    expect(File('assets/brand/logo-horizontal.png').existsSync(), isTrue);
    expect(File('pubspec.yaml').readAsStringSync(), contains('assets/brand/'));
  });
}
